use super::*;

/// What the target actually receives: the request, plus how to answer it.
///
/// The loop id has to travel WITH the request rather than sit in a store the session would have to go
/// looking for — the previous design put it somewhere findable and 20 asks were never found. A session
/// that is handed the request is handed the way to reply in the same breath.
///
/// `reply` rather than `bsc loop say` deliberately: `say` posts a turn and stops there, while `reply`
/// posts it AND delivers it to the other participant, which is what makes the exchange a cycle instead
/// of two messages into a store.
pub fn loop_prompt(loop_id: i64, session_id: &str, request: &str) -> String {
    format!(
        "{request}\n\n\
         [loop {loop_id}] Answer with `bsc session reply {loop_id} \"<your answer>\"` — that delivers it \
         back to whoever asked. If you need something clarified before you can do this, reply with the \
         QUESTION; you will get an answer the same way. Append {ANSWER_SIGNAL} to your final message \
         when the request is fully served, which closes the loop.\n\
         You are `{session_id}` in this loop."
    )
}
